"""Original V15 lock/salinity lessons; source facts and synthetic arithmetic are separated."""
from pathlib import Path
import json,re,hashlib,math
H=Path(__file__).resolve().parent
TARGETS={t['id']:t for t in json.loads((H/'targets.json').read_text())}
S={};D={};META={}
def pair(z,e):return z+'~'+e
def source(key,z,en,publisher,url,scope,scopeEn,evidence):
 S[key]=dict(key=key,title=z,titleEn=en,publisher=publisher,url=url,sourceType='primary',scope=scope,scopeEn=scopeEn,evidence=evidence,accessed='2026-10-21')
def compact(cid,focus,rows):
 units=[]
 for row in rows.strip().splitlines():
  if not row.strip():continue
  title,cause,model,verify,failure,mis=[x.strip()for x in row.split(' || ')]
  cz,ce=cause.split('~');mz,me=model.split('~')
  units.append(dict(anchor=title,title=title,mechanism=pair(cz+' '+mz,ce+' '+me),model=pair('原創教學假設，非操作設定。'+mz,'Original teaching assumptions, not operating settings. '+me),verify=verify,practice=verify,failure=failure,misconception=mis))
 assert len(units)==10
 D[cid]=dict(id=cid,focus=focus,units=units)
def generate():
 for cid,d in D.items():
  t=TARGETS[cid];m=META[cid];u=d['units']
  facts=[x['model']for x in u if len(re.findall('[㐀-鿿]',x['model'].split('~')[0]))<=90 and len(re.findall('[A-Za-z]{2,}',x['model'].split('~')[1]))<=45][:6]
  assert len(facts)==6,(cid,len(facts))
  vendors=[]
  for k in m['vendorSources']:
   s=S[k];vendors.append(dict(name=s['publisher'],nameEn=s['publisher'],business='發布相關水利方法、研究或公共工程資訊。',businessEn='Publishes relevant water-engineering methods, research or public project information.',url=s['url'],investorUrl='',security=None,role=s['scope'],roleEn=s['scopeEn']))
  d.update(title=t['title']+'~'+t['titleEn'],discipline=t['discipline'],family='water',summary=m['summary'],history=m['history'],example=m['example'],facts=facts,timeline=[dict(year=y,event=e)for y,e in m['timeline']],codes=m['codes'],landmarks=m['landmarks'],place=m['place'],sources=[{k:v for k,v in S[s].items()if k not in ('evidence','accessed')}for s in m['sources']],vendors=vendors,related=m['related'],architectureNodes=[x['title'].split('~')for x in (u[0],u[2],u[4],u[7],u[9])],architectureEdges=[[0,1],[1,2],[2,3],[3,4],[4,1]])
  (H/'inputs'/f'{cid}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 (H/'locks_coast_research.json').write_text(json.dumps(dict(accessed='2026-10-21',sources=S,courses={k:v['sources']for k,v in META.items()},limits=['Numerical models are declared original synthetic assumptions, not project field values.','Official indexed excerpts are identified separately from directly opened sources.','No source endorsement or investment/security listing is claimed.']),ensure_ascii=False,indent=2)+'\n')
 print('Generated',list(D))
source('lock-hydraulics','船閘水理設計手冊','Hydraulic Design of Navigation Locks EM1110-2-1604','US Army Corps of Engineers','https://www.publications.usace.army.mil/Portals/76/Publications/EngineerManuals/EM_1110-2-1604.pdf?ver=2013-09-04-161107-413','官方書目確認二〇〇六年五月手冊及船閘水理範圍；不把水理手冊當成閘門結構規範。','Official catalogue confirms May2006 guidance and lock hydraulics; it is not treated as a gate structural-design standard.','Official indexed results turn199search0 and turn199search48; publication date May1,2006.')
source('lock-valves','船閘廊道閥門水理設計手冊','Hydraulic Design of Lock Culvert Valves EM1110-2-1610','US Army Corps of Engineers','https://www.publications.usace.army.mil/USACE-Publications/Engineer-Manuals/u43544q/313131302D32/udt_43544_param_direction/descending/?udt_43544_param_page=2','官方書目列二〇一八年九月船閘充排水控制閥手冊；本課孔口係數是合成示意，非手冊指定值。','Official catalogue lists September2018 guidance for filling/emptying valves; the lesson discharge coefficient is synthetic, not a prescribed manual value.','Official indexed turn199search7 confirms September30,2018 and scope.')
